INSERT INTO public.blogs (title,excerpt,content,date,category,featured,image_url,slug,meta_title,meta_description,sales_heading,sales_text,cta_text,cta_enabled,interactive_type,interactive_items)
SELECT $c$Iskrena sućut: 70 tekstova i SMS poruka sućuti$c$, $c$Primjeri iskrene sućuti za svaku situaciju: kratke SMS poruke, sućut prijatelju, kolegi i cijeloj obitelji, vjerski izrazi, telegram i što ne reći ožalošćenima.$c$, $c$<p>Kad netko izgubi blisku osobu, najteže je pronaći prave riječi. Bojimo se reći nešto pogrešno, pa ponekad ne kažemo ništa. A ožalošćenima najviše znači upravo to da se netko sjetio i javio.</p>
<p>Ovdje smo skupili <strong>preko 70 primjera iskrene sućuti</strong>: kratke SMS poruke, tekstove za prijatelja, kolegu i obitelj, vjerske izraze, tekstove za telegram i vijenac te savjete što ne reći. Odaberite tekst koji vam odgovara i slobodno ga prilagodite. Osobna rečenica uvijek vrijedi više od savršene fraze.</p>
<p><strong>U ovom članku:</strong> <a href="#kratke-poruke">kratke poruke</a> · <a href="#cijeloj-obitelji">cijeloj obitelji</a> · <a href="#prijatelju">prijatelju</a> · <a href="#kolegi">kolegi</a> · <a href="#gubitak">gubitak majke, oca, supružnika, djeteta</a> · <a href="#vjerski">vjerski izrazi</a> · <a href="#telegram">telegram i vijenac</a> · <a href="#sto-ne-reci">što ne reći</a> · <a href="#odgovor">kako odgovoriti</a></p>
<h2 id="kratke-poruke">Kratke poruke sućuti (SMS, WhatsApp)</h2>
<p>Kratka poruka je u redu, osobito ako ne možete nazvati ili doći. Dovoljne su jedna do dvije iskrene rečenice.</p>
<ol>
<li>Iskrena sućut. Mislim na tebe i tvoju obitelj.</li>
<li>Žao mi je zbog tvog gubitka. Tu sam ako trebaš razgovor ili tišinu.</li>
<li>Primi moju iskrenu sućut. Neka te sjećanja na nju griju u ovim danima.</li>
<li>Upravo sam čuo/čula tužnu vijest. Iskrena sućut tebi i obitelji.</li>
<li>Nemam prave riječi, ali mislim na vas. Iskrena sućut.</li>
<li>Bio je divan čovjek. Iskrena sućut cijeloj obitelji.</li>
<li>Bila je posebna žena i ostat će u sjećanju svima koji su je poznavali. Iskrena sućut.</li>
<li>Šaljem ti zagrljaj i snagu. Javi se kad budeš mogao/mogla.</li>
<li>Duboko suosjećam s vama. Počivao u miru.</li>
<li>Moje misli su s tobom. Ne moraš odgovarati na ovu poruku.</li>
<li>Žao mi je što ne mogu biti uz tebe. Iskrena sućut, grlim te.</li>
<li>Neka ti uspomene budu utjeha. Iskrena sućut.</li>
<li>Tužna sam zbog vijesti. Ako ti išta treba, tu sam, danju i noću.</li>
<li>Iskrena sućut. Sjećat ću ga se s puno poštovanja.</li>
<li>Nema riječi koje mogu umanjiti bol, ali želim da znaš da nisi sam/sama.</li>
</ol>
<p>Rečenica <em>„Ne moraš odgovarati na ovu poruku”</em> mala je, ali ožalošćenima često znači puno, jer u prvim danima stižu desetci poruka.</p>
<h2 id="cijeloj-obitelji">Iskrena sućut cijeloj obitelji</h2>
<ol start="16">
<li>Iskrena sućut cijeloj obitelji. Neka vam zajedništvo bude snaga.</li>
<li>Primite naše iskrene izraze sućuti. Dijelimo vašu tugu.</li>
<li>Cijeloj obitelji iskrena sućut. Ostat će zauvijek u našim srcima.</li>
<li>U ime naše obitelji primite iskrenu sućut. S poštovanjem čuvamo uspomenu na njega.</li>
<li>Duboko suosjećamo s vama u ovim teškim trenucima. Iskrena sućut.</li>
<li>Iskrena sućut supruzi, djeci i cijeloj obitelji. Bio je dobar susjed i prijatelj.</li>
<li>Neka vam lijepe uspomene olakšaju dane koji dolaze. Iskrena sućut cijeloj obitelji.</li>
<li>Mislimo na vas i molimo za vas. Iskrena sućut.</li>
</ol>
<h2 id="prijatelju">Sućut prijatelju ili prijateljici</h2>
<p>Prijatelju možete pisati toplije i osobnije. Spomenite pokojnika imenom ako ste ga poznavali i ponudite konkretnu pomoć.</p>
<ol start="24">
<li>Tako mi je žao, prijatelju. Tvoj tata bio je jedan od najtoplijih ljudi koje sam upoznao.</li>
<li>Ne znam što reći, ali znam da sam tu. Kad god, za bilo što.</li>
<li>Sjećam se kako se tvoja mama smijala na tvom rođendanu. Takve trenutke ćemo čuvati. Grlim te.</li>
<li>Žao mi je. Ovaj tjedan ja kuham, samo mi reci koji dan ti odgovara.</li>
<li>Znam koliko ti je značio. Tuguj koliko trebaš, ja ne idem nikamo.</li>
<li>Iskrena sućut, draga. Ako želiš pričati o njoj, rado ću slušati.</li>
<li>Žao mi je što prolaziš kroz ovo. Mogu doći u subotu i pomoći oko svega što treba.</li>
<li>Mislim na tebe svaki dan. Ne moraš ništa, samo znaj da sam blizu.</li>
</ol>
<h2 id="kolegi">Sućut kolegi i poslovnom partneru</h2>
<p>Poslovna sućut neka bude kratka i formalna. Dvije do tri rečenice su dovoljne, i u poruci i u e-mailu.</p>
<ol start="32">
<li>Poštovani, primite moju iskrenu sućut zbog smrti Vašeg oca.</li>
<li>U ime cijelog tima izražavamo Vam iskrenu sućut. Mislimo na Vas i Vašu obitelj.</li>
<li>Žao mi je zbog Vašeg gubitka. Uzmite vremena koliko Vam treba, poslovi mogu pričekati.</li>
<li>Primite izraze iskrene sućuti od kolega iz ureda. Uz Vas smo.</li>
<li>Duboko suosjećamo s Vama i Vašom obitelji. Iskrena sućut.</li>
<li>S tugom smo primili vijest o smrti gospodina Horvata. Primite našu iskrenu sućut.</li>
</ol>
<h2 id="gubitak">Sućut za gubitak majke, oca, supružnika ili djeteta</h2>
<h3>Za gubitak majke</h3>
<ol start="38">
<li>Majka je nezamjenjiva. Iskrena sućut, mislim na tebe.</li>
<li>Tvoja mama bila je duša vaše kuće. Neka ti uspomene na nju budu utjeha.</li>
<li>Primi moju iskrenu sućut zbog smrti tvoje majke. Njezina dobrota živi u tebi.</li>
<li>Žao mi je zbog tvoje mame. Ljubav koju ti je dala ostaje zauvijek.</li>
</ol>
<h3>Za gubitak oca</h3>
<ol start="42">
<li>Iskrena sućut zbog smrti tvog oca. Bio je čovjek na kojeg si se uvijek mogao osloniti.</li>
<li>Tvoj tata ostavio je trag u svima nama. Iskrena sućut tebi i obitelji.</li>
<li>Žao mi je. Znam koliko ste bili bliski. Tu sam za tebe.</li>
<li>Primi moju sućut. Ponosan je bio na tebe, to su svi znali.</li>
</ol>
<h3>Za gubitak supruga ili supruge</h3>
<ol start="46">
<li>Iskrena sućut. Vaša ljubav bila je primjer svima nama.</li>
<li>Žao mi je zbog gubitka tvog supruga. Nisi sama, javi se kad god ti zatreba društvo.</li>
<li>Primite moju iskrenu sućut. Godine koje ste proveli zajedno ostaju vaše zauvijek.</li>
<li>Mislim na tebe. Ako ti zatreba pomoć oko papira ili kuće, slobodno reci.</li>
</ol>
<h3>Za gubitak djeteta</h3>
<p>Ovo je najteži gubitak. Ne tražite objašnjenje i ne uspoređujte. Kratko, iskreno i s ljubavlju.</p>
<ol start="50">
<li>Nema riječi za ovakvu bol. Mislim na vas i grlim vas.</li>
<li>Žao mi je, beskrajno. Uz vas smo, koliko god treba.</li>
<li>Vaš anđeo ostaje u našim srcima. Iskrena sućut.</li>
<li>Ne mogu zamisliti vašu bol. Ako mogu išta učiniti, bilo što, tu sam.</li>
</ol>
<h2 id="vjerski">Kršćanski i vjerski izrazi sućuti</h2>
<p>Ako je obitelj vjernička, vjerski izraz može biti posebna utjeha.</p>
<ol start="54">
<li>Iskrena sućut. Neka mu dobri Bog podari vječni mir.</li>
<li>Pokoj vječni daruj joj, Gospodine. Iskrena sućut obitelji.</li>
<li>Molimo za njegovu dušu i za vas. Neka vas Gospodin tješi.</li>
<li>Počivala u miru Božjem. Iskrena sućut.</li>
<li>Neka je Bog primi u svoje kraljevstvo, a vama da snage. Iskrena sućut.</li>
<li>U molitvama smo s vama. Laka mu bila hrvatska zemlja.</li>
<li>„Ja sam uskrsnuće i život. Tko vjeruje u mene, ako i umre, živjet će.” (Iv 11,25) Iskrena sućut.</li>
<li>„Blago ožalošćenima, oni će se utješiti.” (Mt 5,4) Mislimo na vas.</li>
</ol>
<p>Više biblijskih stihova za ovakve prilike pronaći ćete u našem članku o <a href="/blog/biblijski-stihovi-koji-naglasavaju-moc-i-vaznost-ljubavi">biblijskim stihovima o ljubavi</a>.</p>
<h2 id="telegram">Tekst za telegram sućuti i vijenac</h2>
<p>Telegram i vrpca na vijencu traže vrlo kratak tekst. Na vijencu je uobičajeno samo nekoliko riječi i potpis.</p>
<h3>Telegram sućuti</h3>
<ol start="62">
<li>Primite naše iskrene izraze sućuti. Obitelj Kovačić.</li>
<li>Duboko suosjećamo s vama u boli. Iskrena sućut. Ana i Marko.</li>
<li>S tugom smo primili vijest. Iskrena sućut cijeloj obitelji. Kolege iz tvrtke.</li>
<li>Neka mu je vječna slava i hvala. Iskrena sućut. Obitelj Babić.</li>
</ol>
<h3>Natpis na vrpci vijenca</h3>
<ol start="66">
<li>Posljednji pozdrav – obitelj Perić</li>
<li>Zauvijek u našim srcima – tvoji unuci</li>
<li>Počivaj u miru – kolege s posla</li>
<li>S ljubavlju i poštovanjem – susjedi</li>
<li>Hvala ti za sve – tvoja djeca</li>
</ol>
<h2>Sućut ili saučešće?</h2>
<p>U hrvatskom standardnom jeziku uobičajeno je <strong>sućut</strong>, a izrazi su <em>„iskrena sućut”</em> i <em>„izraziti sućut”</em>. Riječ <em>saučešće</em> čuje se u govoru, ali u pisanim porukama i na osmrtnicama prednost ima sućut. Pazite i na pravopis: piše se <strong>sućut</strong>, sa slovom ć, a ne <em>sučut</em>.</p>
<h2 id="sto-ne-reci">Što ne reći ožalošćenima</h2>
<p>Neke rečenice izgovaramo iz najbolje namjere, a zapravo umanjuju tugu ili traže od ožalošćenog da se osjeća bolje prije nego što je spreman. Evo zamjena koje tješe.</p>
<figure><img src="/images/blog/infografike/sucut-sto-reci.webp" alt="Infografika: šest fraza koje ne treba reći ožalošćenima, poput 'Znam kako ti je', i čime ih zamijeniti" width="1100" height="1718" loading="lazy" /><figcaption>Šest čestih fraza i njihove zamjene.</figcaption></figure>
<p>Općenito, izbjegavajte uspoređivanje s vlastitim gubicima, savjete koje nitko nije tražio i pitanja o uzroku smrti. Slušanje je često najbolja sućut.</p>
<h2>Kako izraziti sućut prema tome koliko ste bliski</h2>
<p>Način ovisi o odnosu. Bliskoj osobi javite se osobno, a poznaniku je dovoljna kratka poruka.</p>
<figure><img src="/images/blog/infografike/sucut-koliko-bliski.webp" alt="Infografika: kako izraziti sućut najbližoj obitelji, prijateljima, kolegama i poznanicima, kanal, što reći i što učiniti kasnije" width="1100" height="1504" loading="lazy" /><figcaption>Kanal i ton prema tome koliko ste bliski.</figcaption></figure>
<p>Ako želite znati više o tome kako biti uz nekoga u tuzi i u mjesecima nakon sprovoda, pročitajte naš vodič <a href="/blog/kako-pruziti-podrsku-ozaloscenoj-osobi">kako pružiti podršku ožalošćenoj osobi</a>.</p>
<h2 id="odgovor">Kako odgovoriti na izraze sućuti</h2>
<p>Ako ste vi ti koji primaju sućut, ne morate odgovarati svima pojedinačno. Kad budete spremni, kratka zahvala je sasvim dovoljna.</p>
<ul>
<li>Hvala ti, puno mi znači.</li>
<li>Hvala na lijepim riječima. Bilo bi mu drago da zna koliko ga se ljudi sjećaju.</li>
<li>Hvala što si mislio/mislila na nas.</li>
<li>Hvala ti od srca. Javit ću se kad budem mogao/mogla.</li>
</ul>
<p>Mnoge obitelji nakon sprovoda objave i <a href="/objavi-osmrtnicu">zahvalu</a>, kojom se jednom porukom zahvaljuju svima koji su bili uz njih.</p>
<h2>Sućut na online osmrtnici</h2>
<p>Ako ne možete doći na sprovod ili niste sigurni kako se javiti obitelji, sućut možete izraziti na osmrtnici. Na osmrtnica.com.hr pronađite osmrtnicu, <a href="/zapali-svijecu" data-cta="sucut_svijeca">zapalite svijeću</a> i ostavite nekoliko riječi. Obitelj će vidjeti tko je mislio na njih.</p>
<h2>Česta pitanja</h2>
<h3>Je li u redu izraziti sućut porukom?</h3>
<p>Da. Kratka poruka je danas uobičajena, osobito za kolege i poznanike. Bliskoj osobi poslije poruke ipak se javite i osobno ili telefonom.</p>
<h3>Kada je prekasno izraziti sućut?</h3>
<p>Nikada. Ako ste vijest čuli kasno, napišite to: „Tek sam sada čuo/čula, žao mi je što se javljam kasno.” Sućut tjednima nakon sprovoda često znači više, jer se tada javlja malo tko.</p>
<h3>Kako izraziti sućut nekome koga ne poznajem dobro?</h3>
<p>Kratko i formalno: „Primite moju iskrenu sućut.” Nije potrebno ništa više.</p>
<h3>Treba li spomenuti ime pokojnika?</h3>
<p>Ako ste ga poznavali, da. Ožalošćenima je drago čuti ime osobe koju su izgubili i jedno lijepo sjećanje na nju.</p>$c$, '2026-10-23T15:05:00+00:00', 'Blog', false, 'https://umpvnepxsqfkxjpclkxc.supabase.co/storage/v1/object/public/obituary-photos/blog/inline/podrska-2.jpg', 'iskrena-sucut-tekstovi-poruke', $c$Iskrena sućut: 70 tekstova i SMS poruka sućuti | Osmrtnica$c$, $c$Ne znate što napisati? 70 primjera iskrene sućuti: SMS poruke, tekstovi za prijatelja, kolegu i obitelj, vjerski izrazi i telegram sućuti.$c$, $c$Riječi koje ostaju$c$, $c$Poruke sućuti obitelj pročita jednom. U digitalnom memorijalu sjećanja, fotografije i poruke bližnjih ostaju sačuvane zauvijek.$c$, $c$Izradite digitalni memorijal$c$, true, 'none', '{}'::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = 'iskrena-sucut-tekstovi-poruke');

INSERT INTO public.blogs (title,excerpt,content,date,category,featured,image_url,slug,meta_title,meta_description,sales_heading,sales_text,cta_text,cta_enabled,interactive_type,interactive_items)
SELECT $c$Nasljeđivanje mirovine od supruga: koliko iznosi i kako je ostvariti$c$, $c$Tko ima pravo na mirovinu preminulog supružnika, koliko iznosi obiteljska mirovina (77 %), kada se isplati dio od 27 % uz vlastitu mirovinu i kako predati zahtjev HZMO-u.$c$, $c$<blockquote><p><strong>Ukratko:</strong> mirovina se ne nasljeđuje automatski, ali udovica ili udovac može ostvariti <strong>obiteljsku mirovinu</strong>. Za jednog člana obitelji ona iznosi 77 % mirovine pokojnika. Pravo u pravilu imate ako ste u trenutku smrti supružnika imali barem 50 godina. Od 65. godine možete umjesto toga zadržati vlastitu mirovinu i uz nju primati <strong>27 % obiteljske</strong>. Zahtjev predajte u roku od 6 mjeseci da ne izgubite novac.</p></blockquote>
<p>Nakon smrti supružnika, uz tugu dolaze i praktična pitanja. Jedno od prvih je: <em>što će biti s njegovom ili njezinom mirovinom?</em> Za mnoga kućanstva to je pitanje egzistencije.</p>
<p>U ovom članku objašnjavamo tko ima pravo na mirovinu preminulog supružnika, koliko ona iznosi, kada se više isplati obiteljska, a kada vlastita mirovina, te kako i do kada predati zahtjev. Podaci su provjereni na stranicama <a href="https://www.mirovinsko.hr/hr/obiteljska-mirovina/280" target="_blank" rel="noopener">Hrvatskog zavoda za mirovinsko osiguranje (HZMO)</a> u listopadu 2026.</p>
<h2>Može li se naslijediti mirovina supruga?</h2>
<p>Mirovina nije imovina pa se ne nasljeđuje kao stan ili novac na računu. Ne raspravlja se ni u ostavinskom postupku. Umjesto toga, zakon članovima obitelji daje pravo na <strong>obiteljsku mirovinu</strong>, koja se računa iz mirovine pokojnika.</p>
<p>Pravo ne nastaje samo od sebe. Treba ga zatražiti od HZMO-a i ispuniti uvjete, od kojih je najvažnija vaša dob.</p>
<h2>Tko ima pravo na mirovinu preminulog supružnika?</h2>
<p>Pravo na obiteljsku mirovinu imaju bračni drug, izvanbračni drug, životni partner i razvedeni bračni drug kojem je sud dosudio uzdržavanje, uz uvjete koje propisuje Zakon o mirovinskom osiguranju.</p>
<figure><img src="/images/blog/infografike/mirovina-tko-ima-pravo.webp" alt="Infografika: pravo udovice ili udovca na obiteljsku mirovinu prema dobi u trenutku smrti supružnika: 50 i više, 45 do 50 i ispod 50 godina" width="1100" height="1384" loading="lazy" /><figcaption>Dob u trenutku smrti supružnika najviše određuje pravo.</figcaption></figure>
<ul>
<li><strong>50 godina ili više</strong> u trenutku smrti supružnika: pravo na obiteljsku mirovinu imate trajno.</li>
<li><strong>Između 45 i 50 godina</strong>: pravo nastaje kad navršite 50 godina.</li>
<li><strong>Mlađi od 50</strong>: pravo imate ako ste potpuno izgubili radnu sposobnost prije smrti supružnika ili u roku od godine dana nakon nje, ili dok skrbite o djeci koja imaju pravo na obiteljsku mirovinu.</li>
<li><strong>Izvanbračni drug</strong>: zajednica je morala trajati do smrti i najmanje tri godine, ili kraće ako imate zajedničko dijete. Izvanbračna zajednica utvrđuje se u posebnom sudskom postupku.</li>
<li><strong>Razvedeni supružnik</strong>: ima pravo ako mu je sud dosudio uzdržavanje.</li>
</ul>
<p>Udovica ili udovac mlađi od 50 godina koji ponovno sklopi brak gubi pravo na obiteljsku mirovinu, osim ako se pravo temelji na potpunom gubitku radne sposobnosti.</p>
<h2>Koliko iznosi obiteljska mirovina za suprugu ili supruga?</h2>
<p>Obiteljska mirovina računa se kao postotak mirovine koju je pokojnik primao ili bi je primao. Postotak ovisi o tome koliko članova obitelji dijeli mirovinu:</p>
<ul>
<li>jedan član obitelji: <strong>77 %</strong>,</li>
<li>dva člana: <strong>88 %</strong>,</li>
<li>tri člana: <strong>100 %</strong>,</li>
<li>četiri i više članova: <strong>110 %</strong>.</li>
</ul>
<figure><img src="/images/blog/infografike/mirovina-iznos.webp" alt="Infografika: iznos obiteljske mirovine za jednog do četiri člana obitelji na primjeru mirovine od 600 eura te primjer dijela obiteljske mirovine od 27 posto" width="1100" height="1100" loading="lazy" /><figcaption>Primjer izračuna za mirovinu pokojnika od 600 EUR.</figcaption></figure>
<p>Ako obiteljsku mirovinu dijeli više članova, na primjer udovica i dijete na školovanju, ukupni iznos dijeli se na jednake dijelove. Kad dijete izgubi pravo, mirovina se preračunava za preostale članove.</p>
<p>Ako je pokojnik već bio u mirovini, iznos se prvo uvećava za sva usklađivanja mirovina od dana smrti, a onda se primjenjuje postotak.</p>
<h2>Obiteljska ili vlastita mirovina: što se više isplati?</h2>
<p>Ako imate pravo i na vlastitu i na obiteljsku mirovinu, u pravilu možete primati samo jednu, <strong>po vlastitom izboru</strong>. Od 2023. udovice i udovci imaju i treću mogućnost. Usporedite tri primjera:</p>
<ol>
<li><strong>Vaša mirovina je 350 EUR, a supružnikova je bila 700 EUR.</strong> Obiteljska mirovina iznosila bi 77 % od 700, odnosno 539 EUR. To je više od vaše mirovine, pa se isplati odabrati obiteljsku.</li>
<li><strong>Vaša mirovina je 600 EUR, a supružnikova je bila 500 EUR.</strong> Obiteljska bi iznosila 385 EUR. Isplati se zadržati vlastitu mirovinu i uz nju tražiti dio obiteljske (27 % od 385 = 103,95 EUR), ako ispunjavate uvjete iz sljedećeg odjeljka.</li>
<li><strong>Vaša mirovina je 1.300 EUR.</strong> Već sama prelazi granicu od 1.251,20 EUR, pa dio obiteljske mirovine ne možete dobiti. Ako je i supružnikova mirovina bila manja od vaše, ostaje vam vlastita mirovina.</li>
</ol>
<p>Najsigurnije je zatražiti od HZMO-a da izračuna sve mogućnosti za vaš slučaj.</p>
<h2>Dio obiteljske mirovine od 27 % uz vlastitu mirovinu</h2>
<p>Ovo je pravo koje mnogi ne znaju da imaju. Udovica ili udovac koji prima vlastitu starosnu, prijevremenu starosnu ili invalidsku mirovinu može uz nju primati i <strong>27 % obiteljske mirovine</strong>. Prema <a href="https://www.mirovinsko.hr/hr/pravo-na-dio-obiteljske-mirovine-2526/2526" target="_blank" rel="noopener">HZMO-u</a>, uvjeti su:</p>
<ul>
<li>navršenih <strong>65 godina</strong>,</li>
<li>da ste <strong>jedini korisnik</strong> obiteljske mirovine iza pokojnika (uz iznimke za člana obitelji s potpunim gubitkom radne sposobnosti ili dijete sa statusom osobe s invaliditetom),</li>
<li>da sve vaše mirovine iz hrvatskog sustava zajedno ne prelaze <strong>1.251,20 EUR</strong>. Strane mirovine se ne uračunavaju.</li>
</ul>
<p>Dio obiteljske mirovine ne može biti manji od <strong>46,92 EUR</strong> ni veći od polovice obiteljske mirovine. HZMO navodi primjer: mirovina pokojnika od 400 EUR daje obiteljsku od 308 EUR, a 27 % od toga je 83,16 EUR mjesečno.</p>
<p>Zahtjev se predaje na <strong>tiskanici 1-4a</strong>. Ako već primate obiteljsku mirovinu, ne trebate prilagati druge dokumente. Isplata kreće od prvog dana idućeg mjeseca nakon zahtjeva, a moguće je ostvariti i do 6 mjeseci unatrag, ali ne prije dana kad ste ispunili uvjete.</p>
<p>Iznosi 1.251,20 EUR i 46,92 EUR vezani su uz aktualnu vrijednost mirovine od 15,64 EUR, koja vrijedi od 1. srpnja 2026. Mijenjaju se dva puta godišnje, 1. siječnja i 1. srpnja.</p>
<h2>Može li se raditi uz obiteljsku mirovinu?</h2>
<p>Da, uz ograničenje. Korisnik obiteljske mirovine može raditi <strong>do polovice punog radnog vremena</strong>, na primjer četiri sata dnevno, i zadržati cijelu mirovinu.</p>
<p>Od 1. siječnja 2026. korisnici stariji od 65 godina koji rade više od pola radnog vremena mogu istodobno primati <strong>50 % mirovine</strong>.</p>
<h2>Kako predati zahtjev za obiteljsku mirovinu</h2>
<ol>
<li><strong>Pribavite smrtni list</strong> ili izvadak iz matice umrlih. Kako ga dobiti, objasnili smo u članku <a href="/blog/smrtni-list">smrtni list: gdje se vadi i koliko košta</a>.</li>
<li><strong>Ispunite zahtjev</strong> za priznanje prava na obiteljsku mirovinu (tiskanica 1.4 na stranicama HZMO-a).</li>
<li><strong>Priložite dokumente.</strong> Ako je pokojnik bio umirovljenik, u pravilu trebate izvadak iz matice umrlih, izvadak iz matice vjenčanih izdan nakon smrti (ne stariji od 6 mjeseci) i, ako mirovinu traže i djeca, izvatke iz matice rođenih i potvrdu o školovanju za djecu stariju od 15 godina. Točan popis nalazi se na samoj tiskanici.</li>
<li><strong>Predajte zahtjev</strong> osobno u područnom uredu HZMO-a, poštom ili elektronički putem sustava e-Građani.</li>
<li><strong>Pratite rok.</strong> Ako zahtjev predate u roku od 6 mjeseci od ispunjenja uvjeta, mirovina vam pripada od tog dana. Kasniji zahtjev daje pravo najviše 6 mjeseci unatrag.</li>
</ol>
<p>Ako je pokojnik bio umirovljenik, obiteljska mirovina može početi najranije od prvog dana idućeg mjeseca nakon mjeseca smrti.</p>
<p>Sve korake, popis dokumenata i primjere izračuna složili smo i u <a href="/besplatni-vodic/obiteljska-mirovina" data-cta="guide_link">besplatni vodič „Obiteljska mirovina korak po korak”</a>, koji možete preuzeti i ispisati.</p>
<h2>Kada se gubi pravo na obiteljsku mirovinu?</h2>
<p>Pravo prestaje ili se isplata obustavlja u ovim slučajevima:</p>
<ul>
<li>Udovica ili udovac mlađi od 50 godina ponovno sklopi brak, osim ako je pravo ostvareno zbog potpunog gubitka radne sposobnosti.</li>
<li>Prestane skrb o djeci, ako je pravo ostvareno samo po toj osnovi, a uvjet dobi nije ispunjen.</li>
<li>Korisnik radi više od pola radnog vremena. Tada se isplata obustavlja, uz iznimku za starije od 65 godina opisanu gore.</li>
</ul>
<h2>Česta pitanja</h2>
<h3>Isplaćuje li se mirovina pokojnika automatski udovici?</h3>
<p>Ne. Mirovina pokojnika prestaje, a obiteljsku mirovinu treba zatražiti zahtjevom kod HZMO-a.</p>
<h3>Može li udovac dobiti mirovinu preminule supruge?</h3>
<p>Da. Pravila su jednaka za udovice i udovce.</p>
<h3>Mogu li primati obiteljsku mirovinu iz Hrvatske i mirovinu iz Njemačke?</h3>
<p>Strane mirovine ne uračunavaju se u granicu za dio obiteljske mirovine. Za njemačku ili austrijsku udovičku mirovinu zahtjev se predaje tamošnjem nositelju osiguranja. Više o tome pišemo u <a href="/besplatni-vodic/smrt-u-inozemstvu">vodiču „Smrt u inozemstvu”</a>.</p>
<h3>Što ako se ne slažem s rješenjem HZMO-a?</h3>
<p>Protiv rješenja možete izjaviti žalbu. Rok i nadležno tijelo navedeni su u pouci o pravnom lijeku na kraju rješenja.</p>
<p><em>Ovaj članak daje opće informacije. Za izračun u vašem slučaju obratite se HZMO-u na 01 4595 011 ili 01 4595 022.</em></p>$c$, '2026-10-23T15:10:00+00:00', 'Blog', false, 'https://umpvnepxsqfkxjpclkxc.supabase.co/storage/v1/object/public/obituary-photos/blog/inline/suprug-1.jpg', 'nasljedivanje-mirovine-od-supruga', $c$Nasljeđivanje mirovine od supruga: uvjeti i iznos 2026. | Osmrtnica$c$, $c$Imate li pravo na mirovinu preminulog supruga? Uvjeti po dobi, iznos (77 %, 27 % uz vlastitu), primjeri izračuna, rokovi i zahtjev za HZMO.$c$, $c$Sačuvajte vašu zajedničku priču$c$, $c$Uz papirologiju, sačuvajte i ono najvažnije: fotografije, priču vašeg zajedničkog života i poruke bližnjih u digitalnom memorijalu.$c$, $c$Izradite digitalni memorijal$c$, true, 'none', '{}'::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = 'nasljedivanje-mirovine-od-supruga');

